(function(){const siteNavigation=document.getElementById('site-navigation');const siteSearch=document.getElementById('header-site-search-form');const siteHeader=document.getElementById('masthead');if(!siteNavigation){return}
const button=siteNavigation.getElementsByTagName('button')[0];if('undefined'===typeof button){return}
const menu=siteNavigation.getElementsByTagName('ul')[0];if('undefined'===typeof menu){button.style.display='none';return}
if(!menu.classList.contains('nav-menu')){menu.classList.add('nav-menu')}
button.addEventListener('click',function(){siteNavigation.classList.toggle('toggled');document.body.classList.toggle('scroll-lock');if(button.getAttribute('aria-expanded')==='true'){button.setAttribute('aria-expanded','false')}else{button.setAttribute('aria-expanded','true')}});document.addEventListener('click',function(event){const isClickInside=siteNavigation.contains(event.target);if(!isClickInside){siteNavigation.classList.remove('toggled');document.body.classList.remove('scroll-lock');button.setAttribute('aria-expanded','false')}});const links=menu.getElementsByTagName('a');const linksWithChildren=menu.querySelectorAll('.menu-item-has-children > a, .page_item_has_children > a')}())